// rows of intervals with custom labels (confidence levels, drugs)
function ciRows(s, P, rows) {
  rows.forEach(rw => {
    const y = P.y + rw.f * P.h, x1 = X(P, rw.lo), x2 = X(P, rw.hi), xc = X(P, rw.est);
    s.addShape(pres.shapes.LINE, { x: x1, y, w: x2 - x1, h: 0, line: { color: rw.color, width: 3 } });
    for (const xe of [x1, x2]) s.addShape(pres.shapes.LINE, { x: xe, y: y - 0.12, w: 0, h: 0.24, line: { color: rw.color, width: 3 } });
    s.addShape(pres.shapes.OVAL, { x: xc - 0.08, y: y - 0.08, w: 0.16, h: 0.16, fill: { color: rw.color }, line: { color: HEX.white, width: 1 } });
    s.addText(rw.name, { x: P.x - 0.85, y: y - 0.15, w: 0.75, h: 0.3, fontSize: 14, bold: true, color: rw.color, align: "right", margin: 0, isTextBox: true });
    if (rw.note) s.addText(rw.note, { x: P.x, y: y + 0.16, w: P.w, h: 0.25, fontSize: 11, color: HEX.gray, align: "center", margin: 0, isTextBox: true });
  });
}

// false-positive rates when the true effect is 0 (200,000 simulated studies, numpy seed 1)
function chancesSlide(s) {
  const rows = [
    ["One test at α = 0.05", 0.05, HEX.gray],
    ["One estimate, reported at 90/95/99%", 0.099, HEX.gray],
    ["Peek every 10 patients, stop once p < 0.05", 0.192, HEX.pink],
    ["Best of 5 outcomes, p < 0.05", 0.226, HEX.pink],
  ];
  const x0 = 4.3, wMax = 4.6, scale = wMax / 0.25, top = 1.3, rowH = 0.62;
  s.addText("False-positive rate when the true effect is 0", { x: 0.4, y: 0.95, w: 9, h: 0.3, fontSize: 14, bold: true, color: HEX.black, margin: 0, isTextBox: true });
  rows.forEach(([label, v, c], i) => {
    const y = top + 0.15 + i * rowH;
    s.addText(label, { x: 0.4, y, w: x0 - 0.55, h: 0.4, fontSize: 14, color: HEX.gray, align: "right", valign: "middle", margin: 0, isTextBox: true });
    s.addShape(pres.shapes.RECTANGLE, { x: x0, y: y + 0.06, w: v * scale, h: 0.28, fill: { color: c }, line: { color: c } });
    s.addText(`${Math.round(v * 100)}%`, { x: x0 + v * scale + 0.08, y, w: 0.7, h: 0.4, fontSize: 14, bold: true, color: c === HEX.pink ? HEX.pink : HEX.black, valign: "middle", margin: 0, isTextBox: true });
  });
  s.addText([
    { text: "Gray: descriptions of one result. ", options: { bold: true, color: HEX.black } },
    { text: "Reporting several levels can’t push the error rate above the loosest level you claim. ", options: { color: HEX.gray } },
    { text: "Pink: new chances. ", options: { bold: true, color: HEX.pink } },
    { text: "Each extra try is another roll of the dice, and the reported p-value no longer means what it says.", options: { color: HEX.gray } },
  ], { x: 0.4, y: 4.0, w: 9.2, h: 1.0, fontSize: 14, margin: 0, valign: "top", isTextBox: true });
}

